import sys
import json

# Read input parameters
input_data = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {}
x = int(input_data.get('x', 9))
y = int(input_data.get('y', 62))

# Define the loop sequence of (x, y) coordinates and the action to take at each:
# (9, 62) -> 'Down' -> (9, 63)
# (9, 63) -> 'Left' -> (8, 63)
# (8, 63) -> 'Up' -> (8, 62)
# (8, 62) -> 'Right' -> (9, 62)

loop_map = {
    (9, 62): 'Down',
    (9, 63): 'Left',
    (8, 63): 'Up',
    (8, 62): 'Right'
}

button = loop_map.get((x, y))

if button:
    print(json.dumps([button]))
else:
    # If we are somewhere else in the tall grass patch, path back to the loop at (9, 62)
    if x < 8:
        print(json.dumps(['Right']))
    elif x > 9:
        print(json.dumps(['Left']))
    elif y < 62:
        print(json.dumps(['Down']))
    elif y > 63:
        print(json.dumps(['Up']))
    else:
        print(json.dumps([]))
